SELECT b.board_id AS boardId, b.title, b.content, r.restaurant_name AS restaurantName, b.restaurant_id AS restaurantId, r.category AS category, b.board_img AS boardImg, b.board_tag AS boardTag, b.created_at AS createdAt, b.updated_at AS updatedAt, b.user_no AS userNo, u.nickname AS nickName, u.user_img AS userImg, (SELECT COUNT(*) FROM sns_like WHERE board_id = b.board_id) AS likeCount, (SELECT COUNT(*) FROM sns_comment WHERE board_id = b.board_id) AS commentCount, FALSE AS isLiked FROM sns_board b INNER JOIN user u ON b.user_no = u.user_no LEFT JOIN restaurants r ON b.restaurant_id = r.restaurant_id WHERE b.board_id IN
#{id}
ORDER BY FIELD(b.board_id
, #{id}
)
